inline StatusEnum toStatusEnum(const std::string &status) {
  if (status == "LOCKED")
    return StatusEnum::LOCKED;
  if (status == "UNLOCKED")
    return StatusEnum::UNLOCKED;
  throw std::invalid_argument("Invalid status");
}

